-- The second "What's New" announcement (2026-10-29): Share Your Solution.
-- Run AFTER 2026-10-28-site-updates.sql. Idempotent (upsert by slug).
--
-- Generated by `npm run publish -- --update=share-your-solution --target=static --sql`
-- (video/scripts/publish.mjs), with published_at fixed to 29 Oct 2026 so the
-- hero playlist (newest first) keeps it ahead of Handwritten Worked Solutions
-- (28 Oct) whenever it goes live. The files are served from the site itself
-- (public/video/updates/share-your-solution/), so they only exist once the
-- branch that adds them is deployed: the row is inserted UNPUBLISHED
-- (is_active = false) and made live after that deploy, either at
-- /admin/updates (Publish — it keeps the 29 Oct date) or with:
--
--   UPDATE site_updates SET is_active = true, updated_at = now() WHERE slug = 'share-your-solution';

INSERT INTO site_updates (slug, title, summary, cta_label, cta_href, video_mp4_url, video_webm_url, loop_mp4_url, loop_webm_url, poster_url, captions_vtt_url, is_active, published_at)
VALUES ('share-your-solution', 'Share Your Solution', 'Work out a practice question in your own workspace and share it. Once your teacher approves it, other students see it next to the teacher''s solution, with your name on it.', 'Try a practice question', '/curriculum?c=a-level', '/video/updates/share-your-solution/film-1080p-mvu6uty4.mp4', '/video/updates/share-your-solution/film-1080p-mvu6uty4.webm', '/video/updates/share-your-solution/loop-720p-mvu6uty4.mp4', '/video/updates/share-your-solution/loop-720p-mvu6uty4.webm', '/video/updates/share-your-solution/poster-mvu6uty4.webp', '/video/updates/share-your-solution/captions-mvu6uty4.vtt', false, '2026-10-29 23:50:00+00')
ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, cta_label = EXCLUDED.cta_label, cta_href = EXCLUDED.cta_href, video_mp4_url = EXCLUDED.video_mp4_url, video_webm_url = EXCLUDED.video_webm_url, loop_mp4_url = EXCLUDED.loop_mp4_url, loop_webm_url = EXCLUDED.loop_webm_url, poster_url = EXCLUDED.poster_url, captions_vtt_url = EXCLUDED.captions_vtt_url,
  published_at = coalesce(site_updates.published_at, EXCLUDED.published_at), updated_at = now();
